```
   A driver card gets no `tracker` property, so it is stored exactly as today.

5. Both report routes. After their 410 lines (2463 and 2529) add:
   `if (c.tracker) return send(res, 404, { error: 'this link takes ticks, not reports' });`
   It is not counted, because it is a right key. This closes the 6 MB report body to anyone holding a sheet.

6. NEW ROUTE, placed before the card HTML route comment (line 2566):
```js
    if ((m = p.match(/^\/d\/([A-Za-z0-9_-]+)\/ticks$/))) {
      const token = m[1], c = cards[token];
      if (!c || !CARD_TOKEN_RE.test(token)) return wrongKey(req, res, 404, { error: 'that link is not one of ours, or it has been withdrawn' });   // counted, like the report routes
      if (!c.tracker) return send(res, 404, { error: 'this card has no tracker' });                                                                // right key: not counted
      if (cardExpired(c)) return send(res, 410, { error: 'this tracker has finished — ring the number on the sheet' });
      const box = ticksFor(token) || { seq: 0, list: [] };
      if (req.method === 'GET') {   // memory only: no open counted, nothing saved, no log line
        const since = Math.max(0, parseInt(url.searchParams.get('since') || '0', 10) || 0);
        return send(res, 200, { now: new Date().toISOString(), seq: box.seq, ticks: box.list.filter(x => x.seq > since).map(x => tickOut(x, false)) });
      }
      if (req.method !== 'POST') return send(res, 405, { error: 'GET or POST' }, { Allow: 'GET, POST' });
      const declared = parseInt(req.headers['content-length'] || '0', 10);
      if (Number.isFinite(declared) && declared > MAX_TICK_BODY) return send(res, 413, { error: 'a tick is small; that was not one' });
      let body;
      try { body = JSON.parse((await readBody(req, MAX_TICK_BODY)).toString('utf8')); } catch (e) { return send(res, 400, { error: 'that did not arrive as a tick' }); }
      if (!plainObject(body)) return send(res, 400, { error: 'a tick is a JSON object' });
      const id = String(body.id || ''), row = String(body.row || ''), day = String(body.day || '');
      if (!TICK_ID_RE.test(id)) return send(res, 400, { error: 'a tick needs the id its phone made' });
      if (!c.tracker.rows.includes(row)) return send(res, 400, { error: 'that location is not on this tracker' });
      if (!c.tracker.days.includes(day)) return send(res, 400, { error: 'that day is not on this tracker' });
      if (typeof body.done !== 'boolean') return send(res, 400, { error: 'done is true or false' });
      const now = Date.now(), tap = typeof body.tapped_at === 'string' ? Date.parse(body.tapped_at) : NaN;
      const tick = { id, seq: 0, row, day, done: body.done, at: new Date(now).toISOString(),
        tapped_at: Number.isFinite(tap) && tap <= now + 10 * 60 * 1000 && tap >= now - 48 * 3600 * 1000 ? new Date(tap).toISOString() : null,   // the phone's clock, labelled as the phone's
        name_given: String(body.name || '').replace(/[\u0000-\u001f\u007f]/g, '').trim().slice(0, 80) || null,
        source: 'ticked on the servicing tracker', verified: false };
      const was = box.list.find(x => x.id === id);
      if (was) {
        if (was.row === row && was.day === day && was.done === tick.done && was.name_given === tick.name_given)
          return send(res, 200, { saved: true, already: true, tick: tickOut(was, false), now: tick.at });
        return send(res, 409, { error: 'that tick id was already used for a different tick', tick: tickOut(was, false) });
      }
      if (box.list.length >= MAX_TICKS_PER_CARD || ticksTotal() >= MAX_TICKS_TOTAL) return send(res, 507, { error: 'this tracker is full — ring the number on the sheet', full: true });
      const fresh = !ticksFor(token);
      tick.seq = box.seq + 1; box.seq = tick.seq; box.list.push(tick); if (fresh) ticks[token] = box;
      const terr = persistTicks();
      if (terr) {   // not on the disk, so not in memory either: the retry must save, not say "already"
        box.list.pop(); box.seq -= 1; if (fresh) delete ticks[token];
        logWrite({ at: tick.at, what: 'tracker tick NOT SAVED', token, row, day, error: terr.message });
        return send(res, 507, { error: 'the service could not keep that tick — it stays on your phone and goes again' });
      }
      logWrite({ at: tick.at, what: 'tracker tick', token, load: c.load, row, day, done: tick.done, by_name_given: tick.name_given });
      return send(res, 200, { saved: true, tick: tickOut(tick, false), now: tick.at });
    }
```
   The Content-Length check is needed: readBody destroys the socket when it goes over the limit (line 671), and the prototype showed a 413 can only be answered before reading. An untick is a tick with done:false; nothing is ever deleted. `seq` is the order of arrival and the read cursor. The check, push, save and rollback run synchronously, so nothing can slip in between.

